#!/usr/bin/env python3
"""Generate app/src/data/contract.ts from contracts/*.schema.json (do not edit the output by hand).

Usage: python3 scripts/gen_types.py
"""
import json, pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
OUT = ROOT / "app/src/data/contract.ts"


def ts_type(s):
    if "enum" in s:
        return " | ".join("null" if v is None else json.dumps(v) for v in s["enum"])
    t = s.get("type", "string")
    types = t if isinstance(t, list) else [t]
    parts = []
    for x in types:
        if x == "array":
            parts.append(f"{ts_type(s.get('items', {'type': 'string'}))}[]")
        else:
            parts.append({"integer": "number", "number": "number", "string": "string",
                          "boolean": "boolean", "null": "null"}.get(x, "unknown"))
    return " | ".join(parts)


def pascal(name):
    return "".join(w.capitalize() for w in name.split("_"))


lines = ["// GENERATED by scripts/gen_types.py from contracts/*.schema.json (contract v1.0). Do not edit.", ""]
entities = []
for p in sorted((ROOT / "contracts").glob("*.schema.json")):
    s = json.loads(p.read_text())
    ent = s["title"]
    entities.append(ent)
    req = set(s.get("required", []))
    lines.append(f"/** {s.get('description', '')} */")
    lines.append(f"export interface {pascal(ent)} {{")
    for f, fs in s["properties"].items():
        doc = (fs.get("description") or "").replace("*/", "")
        lines.append(f"  /** {doc} */")
        lines.append(f"  {f}{'' if f in req else '?'}: {ts_type(fs)};")
    lines.append("}")
    lines.append("")

lines.append("export interface EntityMap {")
for e in entities:
    lines.append(f"  {e}: {pascal(e)};")
lines.append("}")
lines.append("export type EntityName = keyof EntityMap;")
lines.append(f"export const ENTITY_NAMES: EntityName[] = {json.dumps(entities)};")
lines.append("export type Bundle = { bundle_version: string; notes?: string } & { [K in EntityName]?: EntityMap[K][] };")
OUT.parent.mkdir(parents=True, exist_ok=True)
OUT.write_text("\n".join(lines) + "\n")
print(f"wrote {OUT.relative_to(ROOT)} ({len(entities)} entities)")
